from typing import List

class Solution:
    def escapeGhosts(self, ghosts: List[List[int]], target: List[int]) -> bool:
        your_dist = abs(target[0]) + abs(target[1])
        return all(abs(g[0] - target[0]) + abs(g[1] - target[1]) > your_dist for g in ghosts)

class Solution {
public:
    bool escapeGhosts(vector<vector<int>>& ghosts, vector<int>& target) {
        int your_dist = abs(target[0]) + abs(target[1]);
        for (const auto& g : ghosts) {
            if (abs(g[0] - target[0]) + abs(g[1] - target[1]) <= your_dist) return false;
        }
        return true;
    }
};

class Solution {
    public boolean escapeGhosts(int[][] ghosts, int[] target) {
        int yourDist = Math.abs(target[0]) + Math.abs(target[1]);
        for (int[] g : ghosts) {
            if (Math.abs(g[0] - target[0]) + Math.abs(g[1] - target[1]) <= yourDist) return false;
        }
        return true;
    }
}

var escapeGhosts = function(ghosts, target) {
    const yourDist = Math.abs(target[0]) + Math.abs(target[1]);
    for (const g of ghosts) {
        if (Math.abs(g[0] - target[0]) + Math.abs(g[1] - target[1]) <= yourDist) return false;
    }
    return true;
};
